#include <iostream>

void update_number(int* target, int value) {
    // target 指向调用者的变量。星号用来访问那个变量。
    *target = value;
}

int main() {
    // 测试输入留空。修改前输出 10，修改后输出 25。
    int number = 10;
    std::cout << "修改前：" << number << '\n';
    update_number(&number, 25);
    std::cout << "修改后：" << number << '\n';
    return 0;
}
